// Chain detection by address format
const address = $input.first().json.address.trim();
const walletLabel = $input.first().json.wallet_label;
let chain = 'unknown';

if (/^0x[a-fA-F0-9]{40}$/.test(address)) {
  chain = 'evm';
} else if (/^(bc1|[13])[a-zA-HJ-NP-Z0-9]{25,62}$/.test(address)) {
  chain = 'bitcoin';
} else if (/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(address)) {
  // Solana base58 (check last since EVM and BTC have more distinctive prefixes)
  chain = 'solana';
}

return [{
  json: {
    address,
    chain,
    wallet_label: walletLabel,
    scanned_at: new Date().toISOString()
  }
}];

// Fan out per EVM chain. Moralis has no multi-chain batch endpoint,
// so we emit one item per chain and let the HTTP node run per-chain.
const input = $input.first().json;
const chains = ['eth', 'polygon', 'bsc', 'arbitrum', 'optimism', 'base'];

return chains.map(chain => ({
  json: {
    ...input,
    evm_chain: chain
  }
}));

// Normalize Moralis EVM response (one item per chain) to unified Holdings rows
const results = [];

for (const item of $input.all()) {
  const tokens = item.json.result || [];
  const evmChain = item.json.evm_chain || 'eth';
  const walletLabel = $('Detect Chain').first().json.wallet_label;
  const walletAddr = $('Detect Chain').first().json.address;

  for (const t of tokens) {
    if (t.possible_spam) continue;
    const balance = parseFloat(t.balance_formatted || '0');
    const price = parseFloat(t.usd_price || 0);
    const value = parseFloat(t.usd_value || (balance * price));

    // Skip dust (<$1) except native coin
    if (value < 1 && !t.native_token) continue;

    results.push({
      json: {
        wallet_label: walletLabel,
        wallet_address: walletAddr,
        chain: evmChain,
        token_symbol: t.symbol,
        token_name: t.name,
        contract: t.token_address || 'native',
        balance: balance,
        decimals: t.decimals,
        usd_price: price,
        usd_value: value,
        price_24h_change: parseFloat(t.usd_price_24hr_percent_change || 0),
        portfolio_percentage: parseFloat(t.portfolio_percentage || 0),
        logo: t.logo || null,
        native: !!t.native_token,
        source: 'moralis',
        scanned_at: new Date().toISOString()
      }
    });
  }
}

return results;

// Normalize Helius getAssetsByOwner response
const data = $input.first().json;
const result = data.result || {};
const items = result.items || [];
const walletLabel = $('Detect Chain').first().json.wallet_label;
const walletAddr = $('Detect Chain').first().json.address;
const out = [];

// Native SOL
const nb = result.nativeBalance;
if (nb && nb.lamports > 0) {
  const solBalance = nb.lamports / 1e9;
  const solPrice = nb.price_per_sol || 0;
  const solValue = nb.total_price || (solBalance * solPrice);
  if (solValue >= 0.01) {
    out.push({
      json: {
        wallet_label: walletLabel,
        wallet_address: walletAddr,
        chain: 'solana',
        token_symbol: 'SOL',
        token_name: 'Solana',
        contract: 'native',
        balance: solBalance,
        decimals: 9,
        usd_price: solPrice,
        usd_value: solValue,
        native: true,
        source: 'helius',
        scanned_at: new Date().toISOString()
      }
    });
  }
}

// SPL tokens
for (const t of items) {
  if (t.interface !== 'FungibleToken' && t.interface !== 'FungibleAsset') continue;
  const info = t.token_info || {};
  const metadata = t.content?.metadata || {};
  const balance = parseFloat(info.balance || 0) / Math.pow(10, info.decimals || 0);
  const priceInfo = info.price_info || {};
  const price = parseFloat(priceInfo.price_per_token || 0);
  const value = parseFloat(priceInfo.total_price || (balance * price));

  if (value < 1) continue;

  out.push({
    json: {
      wallet_label: walletLabel,
      wallet_address: walletAddr,
      chain: 'solana',
      token_symbol: info.symbol || metadata.symbol || '?',
      token_name: metadata.name || info.symbol || '?',
      contract: t.id,
      balance: balance,
      decimals: info.decimals,
      usd_price: price,
      usd_value: value,
      logo: t.content?.links?.image || null,
      native: false,
      source: 'helius',
      scanned_at: new Date().toISOString()
    }
  });
}

return out;

// Compose BTC row from mempool.space balance + CoinGecko price
const mempool = $('mempool.space: BTC Balance').first().json;
const gecko = $input.first().json;
const walletLabel = $('Detect Chain').first().json.wallet_label;
const walletAddr = $('Detect Chain').first().json.address;

const funded = mempool.chain_stats?.funded_txo_sum || 0;
const spent = mempool.chain_stats?.spent_txo_sum || 0;
const memFunded = mempool.mempool_stats?.funded_txo_sum || 0;
const memSpent = mempool.mempool_stats?.spent_txo_sum || 0;

const balanceSats = (funded - spent) + (memFunded - memSpent);
const balanceBTC = balanceSats / 1e8;
const price = gecko?.bitcoin?.usd || 0;
const change24h = gecko?.bitcoin?.usd_24h_change || 0;
const value = balanceBTC * price;

if (value < 0.01) return [];

return [{
  json: {
    wallet_label: walletLabel,
    wallet_address: walletAddr,
    chain: 'bitcoin',
    token_symbol: 'BTC',
    token_name: 'Bitcoin',
    contract: 'native',
    balance: balanceBTC,
    decimals: 8,
    balance_sats: balanceSats,
    usd_price: price,
    usd_value: value,
    price_24h_change: change24h,
    native: true,
    source: 'mempool+coingecko',
    scanned_at: new Date().toISOString()
  }
}];

// Summary log + compute portfolio totals
const items = $input.all();
const total = items.reduce((s, i) => s + (i.json.usd_value || 0), 0);

console.log(`Scanned wallet: ${items[0]?.json.wallet_label || 'unknown'}`);
console.log(`Found ${items.length} positions, total $${total.toFixed(2)}`);

for (const i of items) {
  console.log(`  ${i.json.chain.toUpperCase()} ${i.json.token_symbol}: ${i.json.balance.toFixed(4)} = $${i.json.usd_value.toFixed(2)}`);
}

// Attach running total to each item so downstream Notion nodes can use it
return items.map(i => ({
  json: {
    ...i.json,
    portfolio_total_usd: total
  }
}));
